	pub fn new(nodes: &[usize]) -> Self {
		Self::try_new_with_parameters(nodes, &[]).expect("invalid generated Verilog-A instance defaults")
	}

	/// Resolve overrides and dependent defaults before validating the instance.
	pub fn try_new_with_parameters(nodes: &[usize], assignments: &[GeneratedParameterAssignment<'_>]) -> Result<Self, String> {
		Self::try_new_with_simulation_parameters(nodes, assignments, &GeneratedSimulationParameters::default())
	}

	/// Capture simulator queries before resolving parameter defaults and ranges.
	pub fn try_new_with_simulation_parameters(nodes: &[usize], assignments: &[GeneratedParameterAssignment<'_>], simulation_parameters: &GeneratedSimulationParameters) -> Result<Self, String> {
		if nodes.len() != Self::NODE_COUNT { return Err(format!("generated Verilog-A node count mismatch: expected {}, got {}", Self::NODE_COUNT, nodes.len())); }
		let mut mapped = [0usize; Self::NODE_COUNT];
		mapped.copy_from_slice(nodes);
		let params = Parameters::new_box_with_simulation_parameters(simulation_parameters);
		let model_params = params.clone();
		let mut instance = Self {
			nodes: mapped,
			branches: [0usize; Self::BRANCH_COUNT],
			params,
			model_params,
			param_given: boxed_zero_bool_array::<{ Self::PARAMETER_COUNT }>(),
			model_param_given: boxed_zero_bool_array::<{ Self::PARAMETER_COUNT }>(),
			multiplicity: 1.0,
			port_connected: [true; Self::TERMINAL_COUNT],
			stamp_state: StampState::new_box(),
			time: 0.0,
			timestep: 0.0,
			ddt_coefficients: GeneratedDdtCoefficients::inactive(),
			event_state_accepted: boxed_zero_f64_array(),
			event_state_candidate: boxed_zero_f64_array(),
			canonical_reactive: boxed_zero_f64_array(),
			canonical_output_record: boxed_zero_f64_array(),
			canonical_model_values: None,
			canonical_staged: boxed_zero_f64_array(),
			canonical_instance_valid: false,
			canonical_temperature_valid: false,
			canonical_temperature: 0.0,
			canonical_thermal_voltage: 0.0,
		};
		instance.apply_parameters(assignments)?;
		Ok(instance)
	}

	#[doc(hidden)]
	pub fn capture_rollback_state(&self) -> GeneratedVerilogARollbackState {
		let mut values = Vec::with_capacity(336);
		values.extend_from_slice(&self.stamp_state.ddt_current);
		values.extend_from_slice(&self.stamp_state.ddt_previous);
		values.extend_from_slice(&self.stamp_state.ddt_older);
		values.extend_from_slice(&self.stamp_state.ddt_derivative_current);
		values.extend_from_slice(&self.stamp_state.ddt_derivative_previous);
		values.extend_from_slice(&self.stamp_state.idt_current);
		values.extend_from_slice(&self.stamp_state.idt_candidate_previous);
		values.extend_from_slice(&self.stamp_state.idt_input_current);
		values.extend_from_slice(&self.stamp_state.idt_previous);
		values.extend_from_slice(&self.stamp_state.idt_older);
		values.extend_from_slice(&self.stamp_state.idt_input_previous);
		values.extend_from_slice(&*self.event_state_accepted);
		values.extend_from_slice(&*self.event_state_candidate);
		values.extend_from_slice(&*self.canonical_output_record);
		let mut flags = Vec::with_capacity(40);
		flags.extend_from_slice(&self.stamp_state.ddt_initialized);
		flags.extend_from_slice(&self.stamp_state.idt_initialized);
		flags.extend_from_slice(&self.stamp_state.ddt_candidate_valid);
		flags.extend_from_slice(&self.stamp_state.idt_candidate_valid);
		GeneratedVerilogARollbackState { values, flags, ..Default::default() }
	}

	#[doc(hidden)]
	pub fn restore_rollback_state(&mut self, state: &GeneratedVerilogARollbackState) {
		debug_assert_eq!(state.values.len(), 336);
		debug_assert_eq!(state.flags.len(), 40);
		debug_assert_eq!(state.idtmod.len(), Self::IDTMOD_STATE_COUNT);
		let mut rollback_values = state.values.as_slice();
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_older.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_derivative_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_derivative_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_candidate_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_input_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_older.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_input_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::EVENT_STATE_COUNT);
		self.event_state_accepted.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::EVENT_STATE_COUNT);
		self.event_state_candidate.copy_from_slice(field);
		rollback_values = remaining;
		let mut rollback_flags = state.flags.as_slice();
		let (field, remaining) = rollback_flags.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_initialized.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_initialized.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_candidate_valid.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_candidate_valid.copy_from_slice(field);
		rollback_flags = remaining;
		let (record, remaining) = rollback_values.split_at(195);
		self.canonical_output_record.copy_from_slice(record);
		rollback_values = remaining;
		debug_assert!(rollback_values.is_empty());
		debug_assert!(rollback_flags.is_empty());
	}

